mapper.delete:
 				delete from FIN_CASH_INFO
 				where
 				CASH_ID=#{cashId,jdbcType=VARCHAR}

 				and FINPROD_ID=#{finprodId,jdbcType=VARCHAR}


 				AND BRANCH=#{branch,jdbcType=DECIMAL}


	 				AND CASH_TYPE_1=#{cashType1,jdbcType=VARCHAR}


	 				AND CASH_TYPE_2=#{cashType2,jdbcType=VARCHAR}

mapper.select:
			select  CASH_ID cashId, CASH_TYPE_1 cashType1, CASH_TYPE_2 cashType2, CCY ccy, FINPROD_ID finprodId, 
       FINPROD_TYPE finprodType, BRANCH branch, FEE_ID feeId, CHL_FINPROD_ID chlFinprodId, 
       CHL_LEVEL chlLevel, CREATE_USER createUser, 
       CREATE_DEPT createDept, CREATE_TIME createTime, UPDATE_USER updateUser, UPDATE_TIME updateTime
       	from FIN_CASH_INFO
       	where
       	FINPROD_ID=#{finprodId,jdbcType=VARCHAR}

				AND BRANCH=#{branch,jdbcType=DECIMAL}


				AND CASH_ID=#{cashId,jdbcType=DECIMAL}


				AND CASH_TYPE_1=#{cashType1,jdbcType=VARCHAR}


				AND CASH_TYPE_2=#{cashType2,jdbcType=VARCHAR}
